create or replace function public.issue_learning_credentials(p_actor_user_account_id uuid,p_journey_instance_id uuid,p_step_instance_id uuid,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$ declare c jsonb; h text; e uuid; old jsonb; b jsonb; cert jsonb; result jsonb; entrepreneur uuid; organization uuid; display_name text; begin perform app_private.e14_validate_idempotency_key(p_idempotency_key); c:=app_private.learning_credential_context(p_actor_user_account_id,p_journey_instance_id,p_step_instance_id); entrepreneur:=(c->>'entrepreneur_id')::uuid; organization:=(c->>'organization_id')::uuid; display_name:=c->>'display_name'; h:=app_private.e14_request_hash(jsonb_build_object('journey_instance_id',p_journey_instance_id,'step_instance_id',p_step_instance_id)); e:=app_private.e14_command_event_id('issue_learning_credentials',p_actor_user_account_id,p_journey_instance_id,p_idempotency_key); select payload into old from eventing.events where event_id=e; if found then if old->>'request_hash'<>h then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='23505'; end if; return jsonb_build_object('request_id',e,'idempotency_key',p_idempotency_key,'replayed',true,'data',old->'result'); end if; b:=app_private.learning_badge_candidates(c); cert:=app_private.learning_certificate_candidates(c); result:=jsonb_build_object('journey_instance_id',p_journey_instance_id,'step_instance_id',p_step_instance_id,'journey_completed',c->>'journey_status'='completed','required_steps_completed',(c->>'required_steps_completed')::boolean,'required_assessments_passed',(c->>'required_assessments_passed')::boolean,'badges',b,'certificates',cert); perform app_private.e14_append_event(e,'learning.credentials.issued','journey_instance',p_journey_instance_id,'user_account',p_actor_user_account_id,organization,p_journey_instance_id,'credential_issue',e,1,e,null,jsonb_build_object('journey_instance_id',p_journey_instance_id,'step_instance_id',p_step_instance_id,'request_hash',h,'result',result)); insert into engagement.badge_awards(id,entrepreneur_id,journey_instance_id,badge_version_id,source_event_id,evidence_snapshot,awarded_at) select (x->>'award_id')::uuid,entrepreneur,p_journey_instance_id,(x->>'badge_version_id')::uuid,e,jsonb_build_object('scope',x->>'scope','step_instance_id',x->'step_instance_id','rule_version_id',x->>'rule_version_id','journey_status',c->>'journey_status','required_steps_completed',(c->>'required_steps_completed')::boolean,'required_assessments_passed',(c->>'required_assessments_passed')::boolean),clock_timestamp() from jsonb_array_elements(b) x on conflict (entrepreneur_id,journey_instance_id,badge_version_id) do nothing; insert into engagement.certificate_issuances(id,entrepreneur_id,journey_instance_id,certificate_version_id,verification_code,display_name_snapshot,requirement_snapshot,source_event_id,status,issued_at,expires_at) select (x->>'issuance_id')::uuid,entrepreneur,p_journey_instance_id,(x->>'certificate_version_id')::uuid,x->>'verification_code',display_name,jsonb_build_object('journey_title',c->>'journey_title','journey_status',c->>'journey_status','required_steps_completed',(c->>'required_steps_completed')::boolean,'required_assessments_passed',(c->>'required_assessments_passed')::boolean,'rule_version_id',x->>'rule_version_id'),e,'active',clock_timestamp(),(x->>'expires_at')::timestamptz from jsonb_array_elements(cert) x on conflict (journey_instance_id,certificate_version_id) do nothing; return jsonb_build_object('request_id',e,'idempotency_key',p_idempotency_key,'replayed',false,'data',result); end; $$; revoke all on function public.issue_learning_credentials(uuid,uuid,uuid,text) from public,anon,authenticated; grant execute on function public.issue_learning_credentials(uuid,uuid,uuid,text) to service_role,app_worker;
